import sys
import threading
from collections import deque

def main():

	def bfs(node, parent, color):
		queue = deque([[node, parent, color]])
		while queue:
			(node, parent, color) = queue.popleft()
			visited[node - 1] = color
			if node in dic:
				for nbr in dic[node]:
					if visited[nbr - 1] == 0:
						queue.append([nbr, node, 3 - color])
					elif nbr != parent and visited[nbr - 1] == color:
						return False
		return True
	for _ in range(int(input())):
		n = int(input())
		dic = {}
		flag = True
		for _ in range(n):
			(x, y) = list(map(int, sys.stdin.readline().split()))
			if x == y:
				flag = False
			else:
				if x not in dic:
					dic[x] = []
				if y not in dic:
					dic[y] = []
				dic[x].append(y)
				dic[y].append(x)
				if len(dic[x]) > 2 or len(dic[y]) > 2:
					flag = False
		if not flag:
			print('NO')
		else:
			visited = [0] * n
			flag = True
			for i in range(1, n + 1):
				if visited[i - 1] == 0:
					if not bfs(i, -1, 1):
						flag = False
						break
			if flag:
				print('YES')
			else:
				print('NO')
sys.setrecursionlimit(2 ** 32 // 2 - 1)
threading.stack_size(1 << 27)
thread = threading.Thread(target=main)
thread.start()
thread.join()
